  TIMING,
  springIn,
  staggeredSpring,
  ambientDrift,
} from "../motion";
import { BRAND } from "@/lib/brand";

export const fps = 25;

const COLORS = {
  bg: BRAND.colors.bg,
  card: BRAND.colors.card,
  border: BRAND.colors.border,
  text: BRAND.colors.text,
  textMuted: BRAND.colors.textMuted,
  textSubtle: BRAND.colors.textSubtle,
  orange: BRAND.colors.orange,
  orangeDeep: BRAND.colors.orangeDeep,
  orangeTint: BRAND.colors.orangeTint,
};

const FONT_MARKETING = "'GT Walsheim', Inter, sans-serif";
const FONT_PRIMARY = "Inter, sans-serif";

const TRANSITION = 15;

// Scene durations
const S1 = 150; // intro: discovery
const S2 = 200; // topic → branches
const S3 = 180; // three directions
const S4 = 150; // outro CTA

const TOTAL =
  20 + // opening black
  20 + // fade
  (S1 + TRANSITION) +
  TRANSITION +
  (S2 + TRANSITION) +
  TRANSITION +
  (S3 + TRANSITION) +
  TRANSITION +
  (S4 + TRANSITION) +
  TRANSITION +
  25; // closing black

export const durationInFrames = TOTAL - 5 * TRANSITION + TRANSITION; // safe sum

// Actually compute total cleanly:
const computeTotal = () => {
  const segs = [20, S1 + TRANSITION, S2 + TRANSITION, S3 + TRANSITION, S4 + TRANSITION, 25];
  const transitions = [20, TRANSITION, TRANSITION, TRANSITION, TRANSITION];
  const sumSeg = segs.reduce((a, b) => a + b, 0);
  const sumT = transitions.reduce((a, b) => a + b, 0);
  return sumSeg - sumT + sumT; // sequences overlap by transition frames already added; simplify below
};

